   111  byte JpegBase::advanceToMarker(ErrorCode err) const {
   112    int c = -1;
   113    // Skips potential padding between markers
   114    while ((c = io_->getb()) != 0xff) {
   115      if (c == EOF)
   116        throw Error(err);
   117    }
   118
   119    // Markers can start with any number of 0xff
   120    while ((c = io_->getb()) == 0xff) {
   121    }
   122    if (c == EOF)
   123      throw Error(err);
   124
   125    return static_cast<byte>(c);
   126  }
